import{_ as a,o as r,c as e,a2 as d}from"./chunks/framework.wVcpyw2-.js";const g=JSON.parse('{"title":"外卖","description":"灵萌外卖后台配置：区域外卖配置、佣金、商家审核、商品与订单派单验收步骤。","frontmatter":{"title":"外卖","description":"灵萌外卖后台配置：区域外卖配置、佣金、商家审核、商品与订单派单验收步骤。"},"headers":[],"relativePath":"features/takeaway.md","filePath":"features/takeaway.md","lastUpdated":1785051348000}'),o={name:"features/takeaway.md"};function l(h,t,n,s,i,b){return r(),e("div",null,[...t[0]||(t[0]=[d('<h1 id="外卖" tabindex="-1">外卖 <a class="header-anchor" href="#外卖" aria-label="Permalink to &quot;外卖&quot;">​</a></h1><p>路径：<strong>商户管理 → 外卖</strong></p><p>按区域开启外卖、审核商家、维护商品，并管理订单与派单。</p><div class="warning custom-block"><p class="custom-block-title">菜单可能显示「内测中」</p><p>部分站点 <strong>商户管理</strong> 分组暂不可进入。请先到 <a href="/config/my-modules">我的模块</a> 确认外卖已开通；若仍显示内测中，请联系交付方。</p></div><hr><h2 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>依赖</th><th>文档</th></tr></thead><tbody><tr><td>外卖模块已授权</td><td><a href="/config/my-modules">我的模块</a></td></tr><tr><td>高德地图 Web Key + 安全密钥</td><td><a href="/features/map">地图与定位</a></td></tr><tr><td>微信支付等</td><td><a href="/features/payment">支付与提现</a></td></tr><tr><td>有可用骑手（派单需要）</td><td><a href="/features/rider">骑手</a></td></tr></tbody></table><hr><h2 id="建议上线顺序" tabindex="-1">建议上线顺序 <a class="header-anchor" href="#建议上线顺序" aria-label="Permalink to &quot;建议上线顺序&quot;">​</a></h2><ol><li><strong>区域外卖配置</strong> — 开区域、配送范围、派单策略</li><li><strong>佣金配置</strong> — 平台抽成</li><li><strong>商家审核</strong> → <strong>商家管理</strong> — 入驻并营业</li><li>维护 <strong>商品分类 / 商品 / 规格小料</strong></li><li>客户端下单测试 → <strong>外卖订单</strong> 观察派单</li><li>（可选）<strong>桌码管理</strong> 堂食扫码</li></ol><hr><h2 id="一、区域外卖配置-必做" tabindex="-1">一、区域外卖配置（必做） <a class="header-anchor" href="#一、区域外卖配置-必做" aria-label="Permalink to &quot;一、区域外卖配置（必做）&quot;">​</a></h2><p>路径：<strong>商户管理 → 外卖 → 区域外卖配置</strong></p><p>为每个校区/社区单独一行，常见项：</p><table tabindex="0"><thead><tr><th>配置方向</th><th>说明</th></tr></thead><tbody><tr><td>是否开通外卖</td><td>总开关；关则用户端无外卖</td></tr><tr><td>配送范围 / 起送价 / 配送费</td><td>直接影响能否下单与费用</td></tr><tr><td>派单策略</td><td>自动派单 / 抢单、超时转派等（以页面选项为准）</td></tr><tr><td>营业时段</td><td>非营业时间不可下单</td></tr><tr><td>其它抽佣或履约参数</td><td>以页面为准</td></tr></tbody></table><p>新区域上线必做此页。</p><hr><h2 id="二、佣金配置" tabindex="-1">二、佣金配置 <a class="header-anchor" href="#二、佣金配置" aria-label="Permalink to &quot;二、佣金配置&quot;">​</a></h2><p>路径：<strong>商户管理 → 外卖 → 佣金配置</strong></p><p>设置平台与商家分成比例、结算相关规则。改前先与商家沟通清楚。</p><hr><h2 id="三、商家与商品" tabindex="-1">三、商家与商品 <a class="header-anchor" href="#三、商家与商品" aria-label="Permalink to &quot;三、商家与商品&quot;">​</a></h2><table tabindex="0"><thead><tr><th>菜单</th><th>作用</th></tr></thead><tbody><tr><td><strong>商家审核</strong></td><td>处理入驻申请：通过 / 拒绝</td></tr><tr><td><strong>商家管理</strong></td><td>营业状态、店铺信息</td></tr><tr><td><strong>商品分类 / 商品管理 / 规格小料</strong></td><td>菜单维护（可协助商家）</td></tr><tr><td><strong>桌码管理</strong></td><td>堂食扫码点餐（若启用）</td></tr></tbody></table><p>建议先用一家测试店跑通下单，再批量审核真实商家。</p><hr><h2 id="四、订单与收益" tabindex="-1">四、订单与收益 <a class="header-anchor" href="#四、订单与收益" aria-label="Permalink to &quot;四、订单与收益&quot;">​</a></h2><table tabindex="0"><thead><tr><th>菜单</th><th>作用</th></tr></thead><tbody><tr><td><strong>外卖订单</strong></td><td>查单、处理异常</td></tr><tr><td><strong>平台收益</strong></td><td>平台佣金收入</td></tr></tbody></table><p>跑腿单在 <strong>跑腿订单</strong>，见 <a href="/features/errand">跑腿</a>。</p><hr><h2 id="验证是否生效" tabindex="-1">验证是否生效 <a class="header-anchor" href="#验证是否生效" aria-label="Permalink to &quot;验证是否生效&quot;">​</a></h2><ol><li>测试区域外卖配置已启用，配送范围覆盖测试地址</li><li>一家测试店审核通过并设为营业，有上架商品</li><li>客户端在该区域能进店、加购、支付</li><li><strong>外卖订单</strong> 出现新单；有在线骑手时能进入配送并完成</li><li><strong>资金交易 / 平台收益</strong> 数据合理</li></ol><hr><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>处理</th></tr></thead><tbody><tr><td>商户管理点不了</td><td>内测中或未授权；见上文警告</td></tr><tr><td>用户看不到外卖</td><td>区域未启用；UI 无入口；不在配送范围</td></tr><tr><td>长时间无人接单</td><td>骑手是否在线；派单策略是否过严；见 <a href="/features/rider">骑手</a></td></tr><tr><td>距离/定位错</td><td><a href="/features/map">地图与定位</a> Key 与安全密钥</td></tr></tbody></table><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/features/errand">跑腿</a></li><li><a href="/features/rider">骑手</a></li><li><a href="/features/map">地图与定位</a></li><li><a href="/features/payment">支付与提现</a></li></ul>',37)])])}const u=a(o,[["render",l]]);export{g as __pageData,u as default};
